CREATE TABLE IF NOT EXISTS organizations (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), email TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','agent','requester')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tickets (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), number INTEGER NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('incident','request','problem','change')), priority TEXT NOT NULL CHECK(priority IN ('low','medium','high','critical')), status TEXT NOT NULL CHECK(status IN ('new','assigned','in_progress','pending','resolved','closed')), requester_id TEXT NOT NULL REFERENCES users(id), assignee_id TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, resolved_at TEXT, UNIQUE(organization_id,number));
CREATE INDEX IF NOT EXISTS idx_tickets_org_status ON tickets(organization_id,status);
CREATE TABLE IF NOT EXISTS ticket_events (id TEXT PRIMARY KEY, ticket_id TEXT NOT NULL REFERENCES tickets(id), actor_id TEXT NOT NULL REFERENCES users(id), event_type TEXT NOT NULL, details TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sla_policies (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), priority TEXT NOT NULL, response_minutes INTEGER NOT NULL, resolution_minutes INTEGER NOT NULL);
